13	## Map known zenka types ##
14	$type = 'CUBE'   if $zenka_name =~ m{^cube}i;
15	$type = 'V7'     if $zenka_name =~ m{^v7}i;
16	$type = 'CODE'   if $zenka_name =~ m{^coding}i;
17	$type = 'MODEL'  if $zenka_name =~ m{^model}i;
18	$type = 'VISION' if $zenka_name =~ m{^lm-vision}i;
19	$type = 'LOG'    if $zenka_name =~ m{^p7-log}i;
20	$type = 'HTTPD'  if $zenka_name =~ m{^httpd}i;
21	
22	## Generate CHKSUM7 from zenka name using AMOS7 ##
23	## Use first 7 chars of AMOS7 checksum ##
24	my $chk_input = "$zenka_name:" . ( <system.hostname> // 'localhost' );
25	
26	## resolve amos checksum sub — works before and after swap ##
27	## use $code{} directly to bypass P7 pre-validation of <[...]> names ##
28	my $amos_chksum = $code{'chk-sum.amos'} // $code{'base.chk-sum.amos'};
29	
30	my $chksum7 = substr( $amos_chksum->($chk_input), 0, 7 );
31	
32	## generate ADDR_B32 — 6 chars from AMOS7 checksum of pubkey ##
33	my $addr_input;
34	if ( exists $keys{'C25519'}{'pubkey'} && length $keys{'C25519'}{'pubkey'} ) {
35	    $addr_input = $keys{'C25519'}{'pubkey'};
36	} else {
37	    $addr_input = $chk_input;    ## deterministic fallback ##
38	}
39	
40	my $addr_b32 = substr( $amos_chksum->($addr_input), 0, 6 );
41	
42	## Assemble P7REF: TYPE:CHKSUM7:ADDR_B32 ##
43	my $p7ref = sprintf( "%s:%s:%s", $type, $chksum7, $addr_b32 );
44	
45	<[base.logs]>->( 2, "[p7ref.self] %s -> %s", $zenka_name, $p7ref );
46	
47	return $p7ref;
